sys_ui_action.script:
// bfd_ui_initiate_payment_reversal — raise the payment reversal work item.
(function initiatePaymentReversalAction() {
    var TASK_TABLE = 'x_1755386_safetr_0_bfd_case_task';

    var amount = current.getValue('disputed_amount') || '0';

    var task = new GlideRecord(TASK_TABLE);
    task.initialize();
    task.setValue('case', current.getUniqueValue());
    task.setValue('task_type', 'payment_reversal');
    task.setValue('status', 'open');
    task.setValue('priority', current.getValue('priority') || 'p2');
    task.setValue(
        'outcome',
        'Payment reversal initiated by ' +
            gs.getUserDisplayName() +
            ' for ' +
            amount +
            ' ' +
            (current.getValue('currency') || '')
    );
    if (current.getValue('assigned_group')) task.setValue('assigned_group', current.getValue('assigned_group'));
    if (current.getValue('assigned_agent')) task.setValue('assigned_agent', current.getValue('assigned_agent'));
    var due = new GlideDateTime();
    due.addDaysLocalTime(3);
    task.setValue('due_date', due.getValue());
    task.insert();

    new bfd_TriageEngine().logAiDecision(current, {
        note:
            'Payment reversal initiated for ' +
            amount +
            '. Task ' +
            task.getValue('number') +
            ' raised with a 3 day due date.',
        finalDecision: 'payment_reversal_initiated',
    });
    current.update();

    gs.addInfoMessage(
        'Payment reversal initiated. Task ' +
            task.getValue('number') +
            ' has been raised and the action is recorded in the audit trail.'
    );
    action.setRedirectURL(current);
})();
